def supp1():
    fig,axs=layout(6);b=pd.read_csv(ROOT/'phase7/results/benchmark/all_fields.csv');b=b[b.setting.eq(BATCHES[0])].copy();summary=b.groupby('split').agg(fields=('field','size'),manual=('manual_objects','sum'),automatic=('predicted_objects','sum')).reindex(['training','validation','test']).reset_index();ax=axs[0];x=np.arange(3);ax.bar(x-.17,summary.manual,width=.34,color=GRAY,label='Manual');ax.bar(x+.17,summary.automatic,width=.34,color=BLUE,label='Automatic');ax.set_xticks(x,['Train n=100','Valid n=50','Test n=50'],fontsize=6.5);ax.set_ylabel('Nuclear objects');ax.legend(frameon=False,fontsize=6.5);emit(ax,'supplementary_figure1','A','External manual benchmark coverage',summary,'200 U2OS chemical-image fields in official splits','Object counts describe segmentation coverage. These chemical images validate measurement transfer and are not independent DYNLL1 perturbations.','BBBC039 primary Run1 scale benchmark')
    ax=axs[1]
    for split,color in [('training',GRAY),('validation',ORANGE),('test',BLUE)]:q=b[b.split.eq(split)];ax.scatter(q.manual_objects,q.F1,s=9,color=color,alpha=.6,label=split)
    ax.set_xlabel('Manual nuclei per field');ax.set_ylabel('Field detection F1');ax.legend(frameon=False,fontsize=6,loc='lower right');emit(ax,'supplementary_figure1','B','Detection performance versus load',b,'200 benchmark fields','Field F1 varies with image context and includes failures and empty manual fields. No trend is selected as evidence of biological perturbation.','phase7/results/benchmark/all_fields.csv')
    t=b[b.split.eq('test')].copy();t['precision']=t.TP/(t.TP+t.FP);t['recall']=t.TP/(t.TP+t.FN);ax=axs[2];ax.scatter(t.recall,t.precision,s=12,color=BLUE,alpha=.7);ax.set_xlabel('Recall');ax.set_ylabel('Precision');ax.set_xlim(0,1.03);ax.set_ylim(0,1.03);emit(ax,'supplementary_figure1','C','Test field precision and recall',t,'50 official held-out test fields','Each point is one field. Detection omissions remain substantial despite high precision; no nucleus-level confidence test is substituted for field sampling.','primary BBBC039 test split')
    objects=[]
    for row in t.itertuples():objects.append(pd.read_parquet(ROOT/f'phase7/results/benchmark/objects/{row.field}__{BATCHES[0]}.parquet'))
    obj=pd.concat(objects,ignore_index=True);obj=obj[obj.manual_eligible].copy();bins=[1.2,1.4,1.6,2.,2.5,np.inf];obj['ARbin']=pd.cut(obj.ar,bins,right=False,labels=['1.2-1.4','1.4-1.6','1.6-2','2-2.5','>=2.5']);group=obj.groupby(['field','ARbin'],observed=True).agg(manual=('nucleus_id','size'),usable=('usable_axis','sum'),mean_error_deg=('absolute_axis_error_deg','mean')).reset_index();group['coverage']=group.usable/group.manual;ax=axs[3]
    for i,label in enumerate(['1.2-1.4','1.4-1.6','1.6-2','2-2.5','>=2.5']):
        q=group[group.ARbin.eq(label)];ax.scatter(i+np.linspace(-.13,.13,len(q)),q.coverage,s=5,color=GRAY,alpha=.4);ax.scatter(i,q.coverage.mean(),s=16,color=BLUE)
    ax.set_xticks(range(5),['1.2-1.4','1.4-1.6','1.6-2','2-2.5','>=2.5'],rotation=25,ha='right',fontsize=6);ax.set_ylabel('Usable axis coverage');emit(ax,'supplementary_figure1','D','Axis coverage across nuclear shapes',group,'field by manual aspect-ratio bin','Coverage is conditional on manual eligibility. Gray points are field-bin fractions and blue points are their means; no cell-level inference is claimed.','manual benchmark objects in50 test fields')
    ax=axs[4]
    for i,label in enumerate(['1.2-1.4','1.4-1.6','1.6-2','2-2.5','>=2.5']):
        q=group[group.ARbin.eq(label)].dropna(subset=['mean_error_deg']);ax.scatter(i+np.linspace(-.12,.12,len(q)),q.mean_error_deg,s=5,color=GRAY,alpha=.4);ax.scatter(i,q.mean_error_deg.mean(),s=16,color=BLUE)
    ax.set_xticks(range(5),['1.2-1.4','1.4-1.6','1.6-2','2-2.5','>=2.5'],rotation=25,ha='right',fontsize=6);ax.set_ylabel('Mean axis error in degrees');emit(ax,'supplementary_figure1','E','Axis error among usable matches',group,'field-bin mean error among matched usable axes','Error summaries exclude unmatched nuclei by definition and must be read with the coverage panel. Small matched errors do not compensate for detection omissions.','manual benchmark usable-axis comparisons')
    q=t[t.manual_adaptive_conditional_focals.ge(20)&t.automatic_adaptive_conditional_focals.ge(20)].copy();ax=axs[5];ax.scatter(q.manual_adaptive_conditional,q.automatic_adaptive_conditional,s=18,color=BLUE);lo=min(q[['manual_adaptive_conditional','automatic_adaptive_conditional']].min())-.02;hi=max(q[['manual_adaptive_conditional','automatic_adaptive_conditional']].max())+.02;ax.plot([lo,hi],[lo,hi],color='black',lw=.6);ax.set_xlabel('Manual field alignment');ax.set_ylabel('Automatic field alignment');ax.text(.03,.95,f'Common fields n={len(q)}',transform=ax.transAxes,va='top',fontsize=7);emit(ax,'supplementary_figure1','F','Spatial measurement agreement',q,'12 common evaluable test fields','Only fields with at least20 eligible manual and automatic focals enter this paired comparison. The measurement difference is not subtracted from a DYNLL1 well contrast because the estimands differ.','primary BBBC039 common test fields');save(fig,'supplementary_figure1')

def supp2():
    fig,axs=layout(6);desc=pd.read_csv(R/'field_descriptors.csv');qc=pd.read_csv(ROOT/'phase6/results/raw/field_measurement_QC.csv');q=desc[['field','role','valid_nuclei','directors']].merge(qc,on='field',validate='one_to_one');ax=axs[0];ax.boxplot([q.valid_nuclei,q.directors,q.primary_eligible],tick_labels=['Valid nuclei','Directors','Focals'],showfliers=False,widths=.5);ax.set_ylabel('Objects per field');emit(ax,'supplementary_figure2','A','Field measurement yield',q,'1809 image fields','All geometry fields are counted, including two with fewer than100 directors. Those two fields are ineligible for new descriptor models; eligible director counts agree with the original615037 records.','phase11 geometry summaries and phase6 focal QC')
    agree=pd.read_csv(ROOT/'phase6/qa/source_segmentation_agreement.csv');agree=agree[agree.source_available&agree.mean_axial_agreement.notna()];groups={'Target':['target'],'Source NT':['source_NT'],'Position':['position_control','position_NT'],'Anchor':['anchor_NT','anchor_noguide']};assert agree.role.isin(sum(groups.values(),[])).all();agree['display_group']=agree.role.map({v:k for k,vs in groups.items() for v in vs});roles=list(groups);ax=axs[1]
    for i,role in enumerate(roles):v=agree.loc[agree.display_group.eq(role),'mean_axial_agreement'].to_numpy();ax.scatter(i+np.linspace(-.15,.15,len(v)),v,s=6,color=COLORS[i],alpha=.5)
    ax.axhline(.9,color='black',ls='--',lw=.6);ax.set_xticks(range(4),[f'{role} n={int(agree.display_group.eq(role).sum())}' for role in roles],rotation=20,ha='right',fontsize=6.5);ax.set_ylabel('Field axial agreement');emit(ax,'supplementary_figure2','B','Agreement with released source axes',agree,'259 fields with a source geometry comparison','The weighted cohort agreement is0.89584, below the0.90 reference. Source availability is incomplete and no favorable field subset is used to pass the reference.','phase6 source_segmentation_agreement.csv')
    overlap=pd.read_csv(ROOT/'phase6/results/density_overlap.csv');mat=overlap.pivot(index='gene',columns='batch',values='target_fraction_inside_NT_01_99').reindex(index=ORDER,columns=BATCHES);ax=axs[2];im=ax.imshow(mat,cmap='Blues',vmin=.5,vmax=1,aspect='auto');ax.set_yticks(range(len(ORDER)),ORDER,fontsize=6.5);ax.set_xticks(range(5),LABELS);plt.colorbar(im,ax=ax,fraction=.045,pad=.02).ax.tick_params(labelsize=6);emit(ax,'supplementary_figure2','C','Source control density support',overlap,'gene by date fractions of target focals','Fractions count target focals within the1st-99th percentiles of source-NT local density. This is support overlap, not proof that density confounding is absent.','phase6 density_overlap.csv')
    retention=pd.read_csv(ROOT/'phase6/results/matching_retention.csv');mat=retention.pivot(index='gene',columns='batch',values='retained_fraction').reindex(index=ORDER,columns=BATCHES);ax=axs[3];im=ax.imshow(mat,cmap='Blues',vmin=.8,vmax=1,aspect='auto');ax.set_yticks(range(len(ORDER)),ORDER,fontsize=6.5);ax.set_xticks(range(5),LABELS);plt.colorbar(im,ax=ax,fraction=.045,pad=.02).ax.tick_params(labelsize=6);emit(ax,'supplementary_figure2','D','Matching retention for every gene',retention,'gene by date matched-focal fractions','Retention uses the original three-control matching rule and fixed density, area and AR calipers. Empty MRE11 coverage remains unfilled.','phase6 matching_retention.csv')
    sites=pd.read_csv(R/'leave_one_site_out.csv');ax=axs[4]
    for i,batch in enumerate(BATCHES):g=sites[sites.batch.eq(batch)];ax.plot(g.omitted_site,g.effect,lw=.8,color=COLORS[i],alpha=.65)
    mean=sites.groupby('omitted_site').effect.mean();ax.plot(mean.index,mean.values,color='black',lw=1.8);ax.set_xticks(range(9));ax.set_xlabel('Omitted site index');ax.set_ylabel('DYNLL1 alignment contrast');zero(ax);emit(ax,'supplementary_figure2','E','Leave one image site out',sites,'nine spatial-sampling diagnostics within five dates','The original control model is held fixed. Thin lines are date estimates and black their mean. Omitting technical sites is not biological replication.','phase11 leave_one_site_out.csv')
    original=pd.read_csv(ROOT/'phase6/results/adaptive_conditional_contrasts.csv');near=pd.read_csv(ROOT/'phase6/results/nearby_NT_position_contrasts.csv');q=original[original.gene.eq('RNF8')][['batch','effect']].merge(near[near.gene.eq('RNF8')][['batch','effect']],on='batch',suffixes=('_original','_NT_nearby'));ax=axs[5]
    for i,row in q.iterrows():ax.plot([0,1],[row.effect_original,row.effect_NT_nearby],marker='o',ms=3,lw=1,color=COLORS[i])
    ax.set_xticks([0,1],['Exact position','Nearby NT']);ax.set_ylabel('RNF8 alignment contrast');zero(ax);emit(ax,'supplementary_figure2','F','RNF8 position control sensitivity',q,'five acquisition dates','The exact-position RNF8 reference is no-guide. A nearby-NT sensitivity is shown separately and does not replace or rescue the failed primary recruitment-module test.','phase6 fixed position-reference sensitivity');save(fig,'supplementary_figure2')

def supp3():
    fig,axs=layout(6);qc=pd.read_csv(R/'screen_library_QC.csv');accs=list(dict.fromkeys(qc.accession));ax=axs[0]
    for i,acc in enumerate(accs):q=qc[qc.accession.eq(acc)];ax.scatter(i+np.linspace(-.13,.13,len(q)),q.total_reads,s=10,color=COLORS[i],alpha=.7)
    ax.set_yscale('log');ax.set_xticks(range(4),[x.replace('GSE','') for x in accs],rotation=20);ax.set_ylabel('Retained read counts per sample');emit(ax,'supplementary_figure3','A','Sequencing depth across raw tables',qc,'39 released sample libraries from four raw-count resources','Depth is calculated before new guide filtering. The original processed tables may already include provider filtering and cannot reconstruct removed reads.','four full processed GEO count tables')
    ax=axs[1]
    for i,acc in enumerate(accs):q=qc[qc.accession.eq(acc)];ax.scatter(i+np.linspace(-.13,.13,len(q)),q.zero_fraction,s=10,color=COLORS[i],alpha=.7)
    ax.set_xticks(range(4),[x.replace('GSE','') for x in accs],rotation=20);ax.set_ylabel('Fraction of guides with zero reads');emit(ax,'supplementary_figure3','B','Guide dropout in each library',qc,'39 released sample libraries','HIF sorted fractions show substantial dropout. GSE232592 already excludes a provider-defined low-count subset, so a low observed zero fraction is not a raw-data quality guarantee.','phase11 raw-count library QC')
    records=[]
    for row in json.loads((ROOT/'phase10/results/screen_QC.json').read_text()):
        for key,value in row.items():
            if '_LFC_spearman_' in key and value is not None:records.append({'contrast':row['contrast'],'level':'Guide' if key.startswith('guide') else 'Gene','pair':key.split('spearman_')[1],'rho':value})
    corr=pd.DataFrame(records);names=list(SHORT);ax=axs[2]
    for j,level in enumerate(['Guide','Gene']):
        for i,name in enumerate(names):q=corr[corr.contrast.eq(name)&corr.level.eq(level)];ax.scatter(q.rho,np.repeat(i+(j-.5)*.15,len(q)),s=9,color=GRAY if j==0 else BLUE,alpha=.65)
    ax.set_yticks(range(13),[SHORT[x] for x in names],fontsize=6.3);ax.set_xlabel('Pairwise replicate Spearman rho');emit(ax,'supplementary_figure3','C','Within contrast replicate agreement',corr,'all labeled replicate pairs within13 contrasts','Gray points are guide-level and blue gene-level correlations. Within-arm growth correlations do not imply high agreement of genotype interaction differences.','phase10 complete screen_QC.json')
    effects=pd.read_csv(ROOT/'phase10/results/DYNLL1_DYNLL2_all_contrasts.csv');ax=axs[3]
    for gene,color,offset in [('DYNLL1',BLUE,-.1),('DYNLL2',ORANGE,.1)]:
        q=effects[effects.gene.eq(gene)].set_index('contrast').reindex(names);ax.scatter(q.eligible_guides,np.arange(13)+offset,s=13,color=color,label=gene)
    ax.set_yticks(range(13),[SHORT[x] for x in names],fontsize=6.3);ax.set_xticks(range(7));ax.set_xlabel('Eligible target guides');ax.legend(frameon=False,fontsize=6);emit(ax,'supplementary_figure3','D','Target coverage after the fixed filter',effects,'gene by screen contrast','A guide count describes coverage and is not a biological sample size. The Pol II resource has only one DYNLL1 guide.','phase10 all guide-coverage and effect table')
    sensitivity=pd.read_csv(ROOT/'phase10/results/normalization_and_count_sensitivity.csv');q=sensitivity[sensitivity.gene.eq('DYNLL1')&sensitivity.sensitivity.str.startswith('denominator_threshold_')].copy();q['threshold']=q.sensitivity.str.extract(r'(\d+)$').astype(int);mat=q.pivot(index='contrast',columns='threshold',values='mean_LFC').reindex(index=names,columns=[0,20,30,50,100]);mat=mat.subtract(mat[30],axis=0);ax=axs[4];im=ax.imshow(mat,cmap='RdBu_r',vmin=-1,vmax=1,aspect='auto');ax.set_yticks(range(13),[SHORT[x] for x in names],fontsize=6.3);ax.set_xticks(range(5),[0,20,30,50,100]);ax.set_xlabel('Mean denominator threshold');plt.colorbar(im,ax=ax,fraction=.045,pad=.02).ax.tick_params(labelsize=6);emit(ax,'supplementary_figure3','E','Count threshold sensitivity',mat.reset_index(),'within-contrast change from the threshold30 estimate','Colors show changes in log2 effect relative to the frozen threshold30 estimate and are capped at plus/minus1 for display. Missing eligible-guide estimates remain blank; outcomes from different screens are not pooled.','phase10 complete count-threshold sensitivities')
    q=effects[effects.gene.eq('DYNLL1')&effects.primary_contrast&effects.ntc_pseudogene_p_two_sided.notna()].copy();ax=axs[5];ax.barh(range(len(q)),-np.log10(q.ntc_pseudogene_p_two_sided),color=[ORANGE if n==1 else BLUE for n in q.eligible_guides]);ax.set_yticks(range(len(q)),[f'{dict(GSE232592_WT_growth="WT grow",GSE232592_WT_etoposide="WT etop",GSE290538_HIF_high_vs_low="HIF hi/lo",GSE283147_dead_vs_live="PolII D/L",GSE283147_growth="PolII grow",GSE233195_screen_vs_input="IF sel")[x]} ({n}g)' for x,n in zip(q.contrast,q.eligible_guides)],fontsize=6);ax.set_xlabel('-log10 control guide-set tail');emit(ax,'supplementary_figure3','F','Non targeting calibration and guide count',q,'exploratory pseudo-gene control calibrations','These are matched control-guide-set null tails, not biological-replicate P values. Orange identifies the single-guide Pol II contrasts. An extreme calibrated tail does not overcome reagent or replicate limitations.','phase10 frozen20000-draw non-targeting calibrations');save(fig,'supplementary_figure3')

def supp4():
    fig,axs=layout(8);threshold=pd.read_csv(R/'hTERT_interaction_threshold_sensitivity.csv');ax=axs[0]
    for gene,color in [('DYNLL1',BLUE),('DYNLL2',ORANGE)]:q=threshold[threshold.gene.eq(gene)];ax.plot(range(len(q)),q.mean_delta,marker='o',ms=3,color=color,label=gene)
    ax.set_xticks(range(5),[0,20,30,50,100]);ax.set_xlabel('Joint denominator threshold');ax.set_ylabel('Median genotype interaction');zero(ax);ax.legend(frameon=False,fontsize=6);emit(ax,'supplementary_figure4','A','hTERT interaction filter sensitivity',threshold,'five joint denominator rules for two genes','Both arms must satisfy a denominator-only rule before within-guide interactions are summarized. Guide counts and discovery percentiles are retained for every threshold.','phase11 hTERT interaction threshold sensitivity')
    seq=pd.read_csv(R/'Brunello_DYNLL1_local_paralog_mismatches.csv');ax=axs[1];cols=['DYNLL1_minimum_local_mismatches','DYNLL2_minimum_local_mismatches'];ax.imshow(seq[cols],cmap='Blues',vmin=0,vmax=6,aspect='auto');ax.set_yticks(range(4),seq.cut_coordinate.astype(str),fontsize=6.5);ax.set_xticks([0,1],['DYNLL1 locus','DYNLL2 locus']);
    for i in range(4):
        for j in range(2):ax.text(j,i,str(seq[cols].iloc[i,j]),ha='center',va='center',fontsize=8)
    emit(ax,'supplementary_figure4','B','Local paralog sequence diagnostic',seq,'four official Brunello target sequences and two retained loci','Values are minimum Hamming mismatches on either strand of the two retained loci. They do not establish genome-wide uniqueness, off-target editing or editing efficiency in the assayed cells.','official Brunello sequences and retained DYNLL1/DYNLL2 reference intervals')
    published=pd.read_csv(R/'published_standardized_vs_new_growth.csv.gz');ax=axs[2];ax.scatter(published.WT_DMSOvT0_L2FC,published.mean_LFC,s=2,color=PALE,rasterized=True);d=published[published.gene.eq('DYNLL1')];ax.scatter(d.WT_DMSOvT0_L2FC,d.mean_LFC,s=22,color=BLUE);ax.set_xlabel('Published standardized score');ax.set_ylabel('New median raw log2 ratio');emit(ax,'supplementary_figure4','C','Published score scale and new estimator',published,'matched gene summaries from GSE232592','Published L2FC-labeled values are standardized to control pseudo-genes. The new values are unscaled median guide ratios, so numerical equality is not expected. Original published FDRs remain unchanged.','primary methods plus original published workbook and new count summaries')
    identity=pd.read_csv(R/'APMS_gene_identity_map.csv');mapped=identity.count_gene.notna()&~identity.ambiguous_duplicate_count_gene;summary=pd.DataFrame({'record':['Raw edges','Clean edges','Network nodes','Mapped nodes','Neighbor genes','Mapped neighbors'],'count':[36872,36842,len(identity),int(mapped.sum()),109,int(pd.read_csv(R/'APMS_group_eligibility.csv').included_in_gene_set_analysis.sum())]});ax=axs[3];ax.bar(range(len(summary)),summary['count'],color=[GRAY,BLUE,GRAY,BLUE,GRAY,BLUE]);ax.set_yscale('log');ax.set_xticks(range(6),summary.record,rotation=35,ha='right',fontsize=5.8);ax.set_ylabel('Records or genes');emit(ax,'supplementary_figure4','D','Network cleaning and gene identity audit',summary,'released edge records and uniquely mapped genes','Source IDs and systematic HGNC aliases recover all109 neighbor records for genotype context. Ambiguous duplicate mappings are excluded explicitly. Edge records and genes are separate units and not biological replicates.','CM4AI raw and cleaned network files; official HGNC and Brunello annotations')
    candidates=json.loads((ROOT/'phase8/results/training_candidates.json').read_text());q=pd.DataFrame([dict(candidate=k,**v) for k,v in candidates.items()]);ax=axs[4]
    for i,row in q.iterrows():ax.scatter(i,row.detection_F1,s=24,facecolors=BLUE if row.calibration_eligible else 'none',edgecolors=BLUE if row.calibration_eligible else ORANGE)
    ax.axhline(float(q.loc[q.candidate.eq('baseline'),'detection_F1'].iloc[0])+.02,color='black',lw=.7,ls='--');ax.set_xticks(range(4),['Base','.999','.995','.99']);ax.set_ylabel('Training detection F1');emit(ax,'supplementary_figure4','E','Stopped segmentation calibration',q,'four candidates on100 training fields','The dashed line is the required0.02 improvement. No eligible candidate advanced. The open point is ineligible because an empty manual image produced too many spatial focals. New-method held-out/JUMP outcomes were not generated.','phase8 training-only calibration and frozen adoption rule')
    b=pd.read_csv(ROOT/'phase7/results/benchmark/all_fields.csv');failed=b[b.setting.eq(BATCHES[0])&b.split.eq('validation')&b.manual_objects.eq(169)&b.predicted_objects.eq(2)];assert len(failed)==1;field=failed.field.iloc[0];manual=pd.read_parquet(ROOT/f'phase7/results/benchmark/geometry/{field}_manual.parquet').assign(kind='Manual');automatic=pd.read_parquet(ROOT/f'phase7/results/benchmark/geometry/{field}_automatic.parquet').assign(kind='Automatic');q=pd.concat([manual,automatic],ignore_index=True);ax=axs[5];ax.scatter(manual.x,manual.y,s=4,color=GRAY,alpha=.6,label='Manual n=169');ax.scatter(automatic.x,automatic.y,s=28,facecolors='none',edgecolors=ORANGE,label='Automatic n=2');ax.set_xlim(0,696);ax.set_ylim(520,0);ax.set_xlabel('Image x pixels');ax.set_ylabel('Image y pixels');ax.legend(frameon=False,fontsize=6,loc='upper left');emit(ax,'supplementary_figure4','F','Preidentified undersegmentation failure',q,'one previously identified validation image','This failure example is intentionally diagnostic, not representative. Manual and predicted object centers are shown in the same image coordinates. The original169-versus2 failure remains in all aggregate benchmark results.','phase7 benchmark manual and predicted geometry')
    predsummary=pd.read_csv(R/'shape_to_alignment_prediction_summary.csv');ax=axs[6];ax.bar(range(2),predsummary.out_of_fold_R2,color=[BLUE,GRAY]);ax.set_xticks(range(2),['Gene held out','Date held out']);ax.set_ylabel('Out of fold R2');zero(ax);emit(ax,'supplementary_figure4','G','Predictability from nuclear scalars',predsummary,'54 observations with nested group-blocked validation','Ridge uses five noncollective nuclear/density summaries and training-fold scaling. Negative R2 indicates poor held-out prediction. This small targeted-panel diagnostic is not a genome-wide redundancy test using complete Cell Painting profiles.','phase11 prediction_policy and nested grouped ridge analysis')
    pred=pd.read_csv(R/'shape_to_alignment_OOF_predictions.csv');q=pred[pred.outer_grouping.eq('gene')&pred.gene.eq('DYNLL1')].set_index('batch').reindex(BATCHES).reset_index();ax=axs[7];ax.plot(range(5),q.alignment,marker='o',ms=3,color=BLUE,label='Observed');ax.plot(range(5),q.predicted_alignment,marker='o',ms=3,color=GRAY,label='Predicted');ax.set_xticks(range(5),LABELS);ax.set_ylabel('DYNLL1 alignment contrast');ax.legend(frameon=False,fontsize=6);zero(ax);emit(ax,'supplementary_figure4','H','Prediction with DYNLL1 left out',q,'five date predictions from the leave-DYNLL1-out fold','No DYNLL1 target outcome is used to fit this fold. Input contrast calibration still uses all available controls, including date controls, so this is not a fully held-out discovery experiment.','phase11 complete out-of-fold prediction table');save(fig,'supplementary_figure4')

def main():
    for function in [supp1,supp2,supp3,supp4]:function();print(function.__name__,'complete',flush=True)
    assert len(REGISTRY)==26
    mainpanels=json.loads((P/'main_panel_registry.json').read_text());allpanels=mainpanels+REGISTRY;(P/'panel_registry.json').write_text(json.dumps(allpanels,indent=2));pd.DataFrame(allpanels).to_csv(P/'panel_registry.csv',index=False);assert len(allpanels)==66
if __name__=='__main__':main()
